import {regionBounds, describeClues, canReview} from './flow-model.js';
const $=id=>document.getElementById(id);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const names=['Choose','Process','Identify','Review','Next view'];
const headings=[['Choose a test image','Start with a sample, or bring a flower of your own.'],['Inspect the processed image','A good identification starts with a flower region you can trust.'],['Every clue has a place','Explore what is visible, and notice what is still uncertain.'],['Review possible matches','Compare the evidence. A suggestion is a starting point, not a final answer.'],['Add one useful view','The right next photo can tell us more than another guess.']];
const state={step:0,max:0,samples:[],selected:null,out:null,bounds:null,source:null,view:'crop',clue:'colour',padding:8,seed:null,busy:false,follow:null,history:[],token:0};
let ownedURLs=new Set();
const imageURL=file=>{const url=URL.createObjectURL(file);ownedURLs.add(url);return url;};
function release(url){if(ownedURLs.delete(url))URL.revokeObjectURL(url);}
function icons(){window.lucide?.createIcons({attrs:{'aria-hidden':'true'}});}
function notify(message){$('notice').textContent=message;$('notice').hidden=!message;}
function button(text,action,primary=false,disabled=false,ico='arrow-right'){return `<button class="button ${primary?'primary':''}" data-action="${action}" ${disabled?'disabled':''}>${ico?icon(ico):''}${text}</button>`;}
function setStep(n){if(state.busy||n>state.max)return;state.step=n;notify('');render();$('title').tabIndex=-1;$('title').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function progress(){ $('progress').innerHTML=`<ol class="steps">${names.map((name,i)=>`<li><button class="step-button ${i<state.step?'complete':''}" data-step="${i}" ${i>state.max||state.busy?'disabled':''} ${state.step===i?'aria-current="step"':''}><span class="step-number">${i<state.step?icon('check'):i+1}</span>${name}</button></li>`).join('')}</ol>`;}
function render(){progress();$('title').textContent=headings[state.step][0];$('subtitle').textContent=headings[state.step][1];$('eyebrow').textContent=state.step===0?'A LITTLE CURIOSITY GOES A LONG WAY':`YOUR OBSERVATION · STEP ${state.step+1} OF 5`;$('content').innerHTML=(state.history.length&&state.step!==4?`<div class="history-note">Earlier views remain available. Each photo is analysed separately. <div class="actions">${state.history.map((h,i)=>`<button class="text-button" data-history="${i}">Return to ${escape(h.selected.title)}</button>`).join('')}</div></div>`:'')+[choose,processScreen,identifyScreen,reviewScreen,followScreen][state.step]();icons();if(state.step>0&&state.step<4)draw();}
function choose(){return `<div class="choose-layout"><section><div class="section-label">Try a sample<span>${state.samples.length} test photos</span></div><div class="gallery">${state.samples.map((s,i)=>`<button class="sample" data-sample="${i}" aria-label="Select ${s.title}" aria-pressed="${state.selected?.src===s.src}"><img src="${s.src}" alt="${s.title}: flower reference photograph" loading="lazy">${state.selected?.src===s.src?`<span class="selection-tick">${icon('check')}</span>`:''}<span class="sample-name">${s.title}</span></button>`).join('')}</div><div class="gallery-note">${icon('scan-eye')}<p class="helper">Look closely, then follow the clues.<br>These sample labels are not used to identify your flower.</p></div></section><section class="preview-column"><div class="section-label">Your selected photo<span>Original image</span></div>${state.selected?`<img class="selected-image" src="${escape(state.selected.src)}" alt="Selected original flower photo"><div class="file-label"><strong>${escape(state.selected.title)}</strong><span>${state.selected.width} × ${state.selected.height}</span></div>`:'<div class="empty-selection">Choose a photo to begin.</div>'}<div class="actions">${button('Process image','process',true,!state.selected||state.busy,'scan')}${button('Upload photo','upload',false,state.busy,'upload')}</div><p class="helper">JPEG, PNG or WebP, up to 10 MB.<br>Your photos are processed in this browser and are not uploaded.</p></section></div>`;}
function workspace(){return `<section class="image-workspace"><div class="view-tabs" aria-label="Image views">${['original','crop','mask',...(state.step>=2?['evidence']:[])].map(v=>`<button class="tab" data-view="${v}" aria-pressed="${state.view===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}<span class="view-meta">${state.out.sample.width} × ${state.out.sample.height} analysis</span></div><div class="canvas-frame ${state.step===1&&state.view==='original'?'tappable':''}"><canvas id="photoCanvas" aria-label="${state.view==='original'?'Original photo. In processing, click the flower to select its region.':state.view==='mask'?'Actual selected flower mask':state.view==='evidence'?'Selected image with measured evidence highlighted':'Actual flower region crop'}"></canvas></div><p class="canvas-caption">${icon('info')}${state.view==='original'&&state.step===1?'Click the flower to choose a region. Or use Select image centre below.':state.view==='mask'?'White pixels are the selected region; dark pixels are excluded.':state.view==='evidence'?'Highlight shows the pixels used for this measurement.':'Image proportions are preserved. A crop may include background or cut-off parts.'}</p>${state.step===1?`<div class="crop-controls"><label for="padding">Crop padding</label><input id="padding" type="range" min="0" max="24" value="${state.padding}"><output id="paddingValue">${state.padding}%</output></div><div class="actions">${button('Select image centre','seed-centre',false,state.busy,'focus')}${button('Select another region','reselect',false,state.busy,'mouse-pointer-2')}</div>`:''}</section>`;}
function check(title,detail,status='observed'){return `<div class="check-row"><span class="status-icon ${status}">${icon(status==='observed'?'check':status==='uncertain'?'circle-alert':'circle')}</span><div><strong>${title}</strong><p>${detail}</p></div></div>`;}
function processScreen(){const out=state.out;return `<div class="photo-layout">${workspace()}<section class="inspector"><h2>First, check the flower</h2><p class="inspector-intro">Does the selected region contain the flower you want to explore?</p>${check('Image ready','Your original photo stays unchanged.')}${check(state.bounds?'Flower region found':'No reliable region found',state.bounds?`${state.seed?'You selected':'Automatically proposed'} a connected region. Check the Mask view before continuing.`:'Try tapping a coloured part of the flower, or choose a clearer photo.',state.bounds?'observed':'uncertain')}${check(out.quality.usable?'Measurements available':'Region needs review',out.quality.usable?(state.bounds?.clipped?'The region touches the image edge. Outline clues will stay uncertain.':'The engine can measure this region; that does not confirm its identity.'):escape(out.quality.issues.join('. ')),out.quality.usable&&!state.bounds?.clipped?'observed':'uncertain')}<div class="actions">${button(out.quality.usable?'Use visible clues':'Continue with uncertain region','identify',true,!canReview(out),'arrow-right')}</div><p class="helper">${canReview(out)&&!out.quality.usable?'Your selected region fills most of this photo. You can inspect it, but its clues and matches will remain uncertain.':'If the mask selects the wrong part, select another region.'} Padding changes the preview, not the measured pixels.</p></section></div><div class="bottom-bar">${button('Choose another photo','choose',false,false,'arrow-left')}<p class="helper">A completed processing step is not a confirmed identification.</p></div>`;}
function identifyScreen(){const clues=describeClues(state.out);return `<div class="photo-layout">${workspace()}<section class="inspector"><h2>Clues in this photo</h2><p class="inspector-intro">Select a clue to inspect its supporting pixels.</p>${!state.out.quality.usable?'<p class="alert-note">The selected region fills most of the photo. These measurements remain uncertain; check the mask or try a wider view.</p>':''}${clues.map(c=>`<button class="clue ${state.clue===c.id?'active':''}" data-clue="${c.id}" aria-pressed="${state.clue===c.id}"><span class="clue-icon"><img src="${clueThumbnail(c.id)}" alt="${c.id==='leaves'?'Illustrative plant context, not detected evidence':'Detail from your selected image'}"></span><span class="clue-body"><strong>${c.title}</strong><span class="state ${c.state}">${icon(c.state==='observed'?'circle-check':c.state==='uncertain'?'circle-alert':'circle')}${c.state==='observed'?'Observed':c.state==='uncertain'?'Uncertain':'Not measured'}</span><p>${c.detail}</p></span></button>`).join('')}</section></div><div class="bottom-bar"><div class="legend"><span>${icon('circle-check')}Observed</span><span>${icon('circle-alert')}Uncertain</span><span>${icon('circle')}Not measured</span></div><div class="actions">${button('Inspect region','inspect',false,false,'arrow-left')}${button('Review matches','review',true)}</div></div>`;}
const featureNames={warm:'Warm colours',pale_or_pink:'Pale or pink colour',pink:'Pink colour',red:'Red colour',yellow:'Yellow colour',blue:'Blue colour',pale:'Pale colour',fill:'Region shape',texture:'Surface variation',center_yellow:'Yellow in the centre',outer_yellow:'Yellow around the outside',color_diversity:'Colour variety'};
function reviewScreen(){return `${state.history.length?`<div class="history-note">Viewing photo ${state.history.length+1}. Earlier photos are retained below. Each photo is analysed independently; these results do not combine views.</div>`:''}<div class="photo-layout">${workspace()}<section class="inspector"><span class="badge">${icon('circle-alert')}Review required</span><h2>Possible matches</h2><p class="inspector-intro">Experimental suggestions from this photo. Match strength is not a probability.</p>${!state.out.quality.usable?'<p class="alert-note">Region quality is uncertain. These candidates may reflect background pixels and are not a confirmed identification.</p>':''}${state.out.candidates.slice(0,3).map((c,i)=>`<article class="candidate"><div class="candidate-heading"><span class="rank">${i+1}</span><div><strong>${escape(c.name)}</strong><small>${escape(c.latin)} · ${escape(c.taxonRank)}</small></div></div><details ${i===0?'open':''}><summary>Why it appears here</summary><ul>${c.evidence.slice(0,6).map(e=>`<li>${escape(featureNames[e.feature]||e.feature)}: ${e.contradiction?'outside':'within'} this candidate’s experimental range.</li>`).join('')}</ul><p>Growth stage is a hypothesis: ${escape(c.stage.replaceAll('_',' '))}.</p></details></article>`).join('')}</section></div><div class="bottom-bar"><p class="helper">${escape(state.out.decision.follow_up)}</p><div class="actions">${button('Check clues','identify',false,false,'arrow-left')}${button('Check the missing clue','next',true)}</div></div>`;}
function followScreen(){const aquatic=state.out.candidates[0]?.id==='waterlily';return `<div class="follow-layout"><div><div class="follow-images"><figure><figcaption>Current photo · original</figcaption><img src="${escape(state.selected.src)}" alt="Current flower photo"></figure><figure><figcaption>Example framing · illustration</figcaption><img src="/assets/flow/wider-view.png" alt="Botanical illustration of a flower with surrounding water and leaves"></figure></div><p class="helper">${aquatic?'Include a complete leaf, the flower, and the water surface.':'Framing example only: include your flower and its surrounding plant. The illustration is not evidence for your photo.'}</p>${state.history.length?`<div class="thumbnail-pair">${state.history.map((h,i)=>`<button data-history="${i}" aria-label="Review earlier photo ${i+1}"><img src="${escape(h.selected.src)}" alt="Earlier photo ${i+1}">Photo ${i+1}</button>`).join('')}</div>`:''}</div><section class="inspector"><h2>One more useful clue</h2><p class="inspector-intro">${escape(state.out.decision.follow_up)}</p><button class="dropzone" data-action="follow-upload">${icon('upload')}<strong>${state.follow?'Choose a different follow-up':'Add a follow-up photo'}</strong><span>Choose from your device · JPEG, PNG or WebP</span></button>${state.follow?`<div class="follow-selected"><img src="${escape(state.follow.src)}" alt="Follow-up preview"><span>${escape(state.follow.title)}<br>${state.follow.width} × ${state.follow.height}</span></div>`:''}<div class="actions">${button('Process new view','process-follow',true,!state.follow,'scan')}${button('Keep as unconfirmed','keep',false,false,'bookmark')}</div><p class="helper">The new photo is processed independently. Your earlier view stays available during this session. Photos are not saved after you close or refresh this page.</p></section></div><div class="bottom-bar">${button('Back to matches','review',false,false,'arrow-left')}<p class="helper">New photo → inspect the region → update the visible clues.</p></div>`;}

function clueThumbnail(id){
 if(id==='leaves')return '/assets/flow/wider-view.png';
 const b=state.bounds;let box=cropBox();
 if(id==='centre'&&b){const size=Math.max(8,Math.min(b.right-b.left+1,b.bottom-b.top+1)*.5);box={x:Math.max(0,b.cx-size/2),y:Math.max(0,b.cy-size/2),w:size,h:size};}
 const c=document.createElement('canvas');c.width=80;c.height=80;const ctx=c.getContext('2d');ctx.fillStyle='#eef0ec';ctx.fillRect(0,0,80,80);const k=Math.min(80/box.w,80/box.h);ctx.drawImage(state.source,box.x,box.y,box.w,box.h,(80-box.w*k)/2,(80-box.h*k)/2,box.w*k,box.h*k);return c.toDataURL();
}

function cropBox(){const b=state.bounds,w=state.source.width,h=state.source.height;if(!b)return {x:0,y:0,w,h};const pad=Math.round(Math.max(b.right-b.left+1,b.bottom-b.top+1)*state.padding/100);const x=Math.max(0,b.left-pad),y=Math.max(0,b.top-pad);return {x,y,w:Math.min(w,b.right+pad+1)-x,h:Math.min(h,b.bottom+pad+1)-y};}
function draw(){const canvas=$('photoCanvas');if(!canvas||!state.source)return;const source=state.source,w=source.width,h=source.height,view=state.view;const region=(view==='crop'||view==='evidence')?cropBox():{x:0,y:0,w,h};const work=document.createElement('canvas');work.width=w;work.height=h;const ctx=work.getContext('2d');ctx.drawImage(source,0,0);const pixels=ctx.getImageData(0,0,w,h),mask=state.out.masks.flower,b=state.bounds;let maxR=1;if(b)for(let p=0;p<mask.length;p++)if(mask[p])maxR=Math.max(maxR,Math.hypot(p%w-b.cx,Math.floor(p/w)-b.cy));
 for(let p=0;p<mask.length;p++){const x=p%w,y=Math.floor(p/w);if(view==='mask'){const v=mask[p]?250:25;pixels.data.set([v,v,v,255],p*4);}else if(view==='evidence'&&state.clue!=='leaves'){let highlight=Boolean(mask[p]);if(state.clue==='centre')highlight=highlight&&Math.hypot(x-b.cx,y-b.cy)<=maxR*.32;if(state.clue==='outline')highlight=highlight&&(x===0||y===0||x===w-1||y===h-1||!mask[p-1]||!mask[p+1]||!mask[p-w]||!mask[p+w]);if(highlight){const tint=state.clue==='outline'?[186,127,33]:[15,133,81];for(let k=0;k<3;k++)pixels.data[p*4+k]=Math.round(pixels.data[p*4+k]*.68+tint[k]*.32);}else for(let k=0;k<3;k++)pixels.data[p*4+k]=Math.round(pixels.data[p*4+k]*.45+240*.55);}}
 ctx.putImageData(pixels,0,0);canvas.width=region.w;canvas.height=region.h;const dest=canvas.getContext('2d');dest.drawImage(work,region.x,region.y,region.w,region.h,0,0,region.w,region.h);const frame=canvas.parentElement, style=getComputedStyle(frame);const fit=Math.min(2,(frame.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight))/region.w,(frame.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom))/region.h);canvas.style.width=`${region.w*fit}px`;canvas.style.height=`${region.h*fit}px`;
 if(view==='original'&&state.seed){dest.strokeStyle='#fff';dest.lineWidth=2;dest.beginPath();dest.arc(state.seed.x*w,state.seed.y*h,5,0,Math.PI*2);dest.stroke();}
 if(state.clue==='leaves'&&view==='evidence')document.querySelector('.canvas-caption').textContent='No leaf detector is available. This view has no verified leaf highlights.';
}
async function load(src){const img=new Image();img.src=src;await img.decode();if(!img.naturalWidth||!img.naturalHeight)throw new Error('This image could not be read.');if(img.naturalWidth*img.naturalHeight>60000000)throw new Error('Choose a photo smaller than 60 megapixels.');return img;}
async function selectPhoto(photo,follow=false){const token=++state.token;state.busy=true;notify('Opening photo…');try{const image=await load(photo.src);if(token!==state.token)return;const selected={...photo,image,width:image.naturalWidth,height:image.naturalHeight};if(follow){release(state.follow?.src);state.follow=selected;}else{for(const url of [...ownedURLs])if(url!==photo.src)release(url);state.selected=selected;state.follow=null;state.out=null;state.source=null;state.seed=null;state.history=[];state.step=0;state.max=0;}notify('');}catch(e){release(photo.src);notify(`Could not open photo. ${e.message} Try JPEG, PNG or WebP.`);}finally{if(token===state.token){state.busy=false;render();}}}
async function processPhoto(seed=null){if(!state.selected||state.busy)return;state.busy=true;notify('Measuring the selected photo…');progress();$('content').classList.add('loading');await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{const image=state.selected.image;const scale=Math.min(1,256/image.naturalWidth,256/image.naturalHeight);const c=document.createElement('canvas');c.width=Math.max(1,Math.round(image.naturalWidth*scale));c.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,c.width,c.height);const out=FlowerEngine.analyze(ctx.getImageData(0,0,c.width,c.height).data,c.width,c.height,ENGINE_PROFILES,{seed});state.out=out;state.source=c;state.seed=seed;state.bounds=regionBounds(out.masks.flower,c.width,c.height);state.step=1;state.max=1;state.view='crop';state.clue='colour';notify('');}catch(e){notify('Could not process this image. Try another photo.');console.error(e);}finally{state.busy=false;$('content').classList.remove('loading');render();}}
function advance(step,view){if(!canReview(state.out))return;state.max=Math.max(state.max,step);if(view)state.view=view;setStep(step);}
let filePurpose='main';function upload(purpose){filePurpose=purpose;$('photoInput').value='';$('photoInput').click();}
$('photoInput').addEventListener('change',()=>{const file=$('photoInput').files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10485760||file.size===0){notify('Choose a JPEG, PNG or WebP photo up to 10 MB. Your current photo is unchanged.');return;}selectPhoto({src:imageURL(file),title:file.name},filePurpose==='follow');});
document.addEventListener('click',async event=>{const target=event.target.closest('button');if(!target||target.disabled||state.busy)return;if(target.dataset.step!==undefined)return setStep(Number(target.dataset.step));if(target.dataset.sample!==undefined)return selectPhoto(state.samples[Number(target.dataset.sample)]);if(target.dataset.view){state.view=target.dataset.view;render();return;}if(target.dataset.clue){state.clue=target.dataset.clue;state.view='evidence';render();return;}if(target.dataset.history!==undefined){const h=state.history[Number(target.dataset.history)];const current={selected:state.selected,out:state.out,source:state.source,bounds:state.bounds,seed:state.seed};Object.assign(state,h);state.history[Number(target.dataset.history)]=current;state.step=canReview(h.out)?3:1;state.max=canReview(h.out)?4:1;state.view='crop';render();return;}
 switch(target.dataset.action){case 'upload':upload('main');break;case 'follow-upload':upload('follow');break;case 'process':await processPhoto();break;case 'choose':setStep(0);break;case 'inspect':setStep(1);break;case 'identify':advance(2,'evidence');break;case 'review':advance(3,'crop');break;case 'next':advance(4);break;case 'reselect':state.view='original';render();notify('Click a coloured part of the flower in the original image.');break;case 'seed-centre':await processPhoto({x:.5,y:.5});break;case 'process-follow':if(state.follow){state.history.push({selected:state.selected,out:state.out,source:state.source,bounds:state.bounds,seed:state.seed});state.selected=state.follow;state.follow=null;await processPhoto();}break;case 'keep':notify('Kept unconfirmed for this session. Your photos stay here until you refresh or close this page.');break;}
});
$('content').addEventListener('input',event=>{if(event.target.id==='padding'){state.padding=Number(event.target.value);$('paddingValue').textContent=state.padding+'%';draw();}});
$('content').addEventListener('click',event=>{if(event.target.id!=='photoCanvas'||state.view!=='original'||state.step!==1||state.busy)return;const r=event.target.getBoundingClientRect();processPhoto({x:(event.clientX-r.left)/r.width,y:(event.clientY-r.top)/r.height});});
$('creditsButton').onclick=()=>$('credits').showModal();$('closeCredits').onclick=()=>$('credits').close();
async function init(){render();try{const response=await fetch('/assets/samples/manifest.json');if(!response.ok)throw new Error();state.samples=await response.json();$('creditList').innerHTML=state.samples.map(s=>`<p><a href="${escape(s.sourcePage)}" target="_blank" rel="noopener">${escape(s.title)}</a> — ${escape(s.author)} · <a href="${escape(s.licenseUrl)}" target="_blank" rel="noopener">${escape(s.license)}</a><br>Original photo retained; gallery thumbnails are cropped for display.</p>`).join('');render();}catch{notify('Sample photos could not be loaded. You can still upload your own.');}icons();}
window.addEventListener('resize',()=>{if(state.step>0&&state.step<4)draw();});
init();
